/**
 * In-memory publish/subscribe Event Bus for inter-service communication.
 * Services MUST NOT call each other directly — all cross-service communication
 * goes through this bus.
 */

type EventCallback = (payload: unknown) => void;

class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event by name. Multiple subscribers per event are supported.
   */
  subscribe(event: string, callback: EventCallback): void {
    const existing = this.subscribers.get(event) ?? [];
    this.subscribers.set(event, [...existing, callback]);
  }

  /**
   * Publish an event, synchronously invoking all registered subscribers.
   */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        console.error(`[EventBus] Error in subscriber for event "${event}":`, err);
      }
    }
  }
}

// Singleton instance shared across all services
export const eventBus = new EventBus();

// ── Well-known event names ──────────────────────────────────────────────────

export const EVENT_TASK_ASSIGNED = "task.assigned";
export const EVENT_TASK_STATUS_CHANGED = "task.statusChanged";
export const EVENT_COMMENT_ADDED = "comment.added";

// ── Typed payloads ──────────────────────────────────────────────────────────

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: string;
  newStatus: string;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

import { randomUUID } from "crypto";

// ── Domain types ────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

// ── Service ─────────────────────────────────────────────────────────────────

export class UserService {
  /** Owned data store — no other service may access this. */
  private store: Map<string, User> = new Map();

  listAll(): User[] {
    return Array.from(this.store.values());
  }

  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  create(input: CreateUserInput): User {
    if (!input.name || input.name.trim() === "") {
      throw new Error("User name is required.");
    }
    if (!input.email || input.email.trim() === "") {
      throw new Error("User email is required.");
    }

    const user: User = {
      id: randomUUID(),
      name: input.name.trim(),
      email: input.email.trim(),
    };

    this.store.set(user.id, user);
    return user;
  }

  update(id: string, input: UpdateUserInput): User | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;

    const updated: User = {
      ...existing,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.email !== undefined ? { email: input.email.trim() } : {}),
    };

    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from "crypto";

// ── Domain types ────────────────────────────────────────────────────────────

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

// ── Service ─────────────────────────────────────────────────────────────────

export class ProjectService {
  /** Owned data store — no other service may access this. */
  private store: Map<string, Project> = new Map();

  listAll(): Project[] {
    return Array.from(this.store.values());
  }

  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  create(input: CreateProjectInput): Project {
    if (!input.name || input.name.trim() === "") {
      throw new Error("Project name is required.");
    }
    if (input.description === undefined || input.description === null) {
      throw new Error("Project description is required.");
    }

    const project: Project = {
      id: randomUUID(),
      name: input.name.trim(),
      description: input.description,
      memberIds: [],
    };

    this.store.set(project.id, project);
    return project;
  }

  update(id: string, input: UpdateProjectInput): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;

    const updated: Project = {
      ...existing,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.description !== undefined ? { description: input.description } : {}),
    };

    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (project.memberIds.includes(userId)) {
      // Already a member — idempotent, return current state
      return project;
    }

    const updated: Project = {
      ...project,
      memberIds: [...project.memberIds, userId],
    };

    this.store.set(projectId, updated);
    return updated;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((id) => id !== userId),
    };

    this.store.set(projectId, updated);
    return updated;
  }
}

import { randomUUID } from "crypto";
import {
  eventBus,
  EVENT_TASK_ASSIGNED,
  EVENT_TASK_STATUS_CHANGED,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "../event-bus.js";

// ── Domain types ────────────────────────────────────────────────────────────

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

// Forward-only status transition table
const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus | null> = {
  todo: "in-progress",
  "in-progress": "done",
  done: null, // terminal state
};

// ── Service ─────────────────────────────────────────────────────────────────

export class TaskService {
  /** Owned data store — no other service may access this. */
  private store: Map<string, Task> = new Map();

  listByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  create(input: CreateTaskInput): Task {
    if (!input.title || input.title.trim() === "") {
      throw new Error("Task title is required.");
    }
    if (!input.projectId) {
      throw new Error("Task projectId is required.");
    }

    const task: Task = {
      id: randomUUID(),
      title: input.title.trim(),
      description: input.description ?? "",
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };

    this.store.set(task.id, task);
    return task;
  }

  update(id: string, input: UpdateTaskInput): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;

    const updated: Task = {
      ...existing,
      ...(input.title !== undefined ? { title: input.title.trim() } : {}),
      ...(input.description !== undefined ? { description: input.description } : {}),
    };

    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Advance task status following the forward-only rule: todo → in-progress → done.
   * Throws if the transition is invalid.
   */
  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.store.get(id);
    if (!task) throw new Error(`Task ${id} not found.`);

    const allowedNext = VALID_TRANSITIONS[task.status];

    if (allowedNext === null) {
      throw new Error(
        `Task is already in terminal status "${task.status}". No further transitions are allowed.`
      );
    }

    if (newStatus !== allowedNext) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
          `Only "${allowedNext}" is allowed next.`
      );
    }

    const oldStatus = task.status;
    const updated: Task = { ...task, status: newStatus };
    this.store.set(id, updated);

    // Publish event — NotificationService subscribes
    const payload: TaskStatusChangedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      oldStatus,
      newStatus,
    };
    eventBus.publish(EVENT_TASK_STATUS_CHANGED, payload);

    return updated;
  }

  /**
   * Assign a task to a user. Publishes task.assigned event.
   */
  assignTask(id: string, assigneeId: string): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated: Task = { ...task, assigneeId };
    this.store.set(id, updated);

    const payload: TaskAssignedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
    };
    eventBus.publish(EVENT_TASK_ASSIGNED, payload);

    return updated;
  }
}

import { randomUUID } from "crypto";
import {
  eventBus,
  EVENT_COMMENT_ADDED,
  CommentAddedPayload,
} from "../event-bus.js";

// ── Domain types ────────────────────────────────────────────────────────────

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
  /** Resolved by the router before calling the service. */
  taskTitle: string;
  /** Resolved by the router before calling the service. */
  authorName: string;
}

// ── Service ─────────────────────────────────────────────────────────────────

export class CommentService {
  /** Owned data store — no other service may access this. */
  private store: Map<string, Comment> = new Map();

  listByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  create(input: CreateCommentInput): Comment {
    if (!input.taskId) throw new Error("Comment taskId is required.");
    if (!input.authorId) throw new Error("Comment authorId is required.");
    if (!input.body || input.body.trim() === "") {
      throw new Error("Comment body is required.");
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body.trim(),
      createdAt: new Date().toISOString(),
    };

    this.store.set(comment.id, comment);

    // Publish event — NotificationService subscribes
    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
    };
    eventBus.publish(EVENT_COMMENT_ADDED, payload);

    return comment;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from "crypto";
import {
  eventBus,
  EVENT_TASK_ASSIGNED,
  EVENT_TASK_STATUS_CHANGED,
  EVENT_COMMENT_ADDED,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from "../event-bus.js";

// ── Domain types ────────────────────────────────────────────────────────────

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ── Service ─────────────────────────────────────────────────────────────────

export class NotificationService {
  /** Owned data store — no other service may access this. */
  private store: Map<string, Notification> = new Map();

  constructor() {
    this.registerSubscriptions();
  }

  // ── Public API ────────────────────────────────────────────────────────────

  listByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  getById(id: string): Notification | undefined {
    return this.store.get(id);
  }

  markAsRead(id: string): Notification | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;

    const updated: Notification = { ...existing, read: true };
    this.store.set(id, updated);
    return updated;
  }

  // ── Private helpers ───────────────────────────────────────────────────────

  private create(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  /**
   * Wire up all event subscriptions. Called once in the constructor.
   * No other service is imported — all data arrives via event payloads.
   */
  private registerSubscriptions(): void {
    // task.assigned → notify the assignee
    eventBus.subscribe(EVENT_TASK_ASSIGNED, (raw) => {
      const payload = raw as TaskAssignedPayload;
      this.create(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}".`
      );
    });

    // task.statusChanged → notify the assignee (if any)
    eventBus.subscribe(EVENT_TASK_STATUS_CHANGED, (raw) => {
      const payload = raw as TaskStatusChangedPayload;
      if (!payload.assigneeId) return; // No assignee — nobody to notify
      this.create(
        payload.assigneeId,
        `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`
      );
    });

    // comment.added → notify the comment author (as an acknowledgement)
    eventBus.subscribe(EVENT_COMMENT_ADDED, (raw) => {
      const payload = raw as CommentAddedPayload;
      this.create(
        payload.authorId,
        `Your comment on task "${payload.taskTitle}" was posted successfully.`
      );
    });
  }
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { TaskStatus } from "./services/task-service.js";

// ── Helpers ──────────────────────────────────────────────────────────────────

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk: Buffer) => (data += chunk.toString()));
    req.on("end", () => {
      if (!data) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error("Invalid JSON body."));
      }
    });
    req.on("error", reject);
  });
}

function send(
  res: ServerResponse,
  status: number,
  body: unknown
): void {
  const json = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(json),
  });
  res.end(json);
}

function sendError(res: ServerResponse, status: number, message: string): void {
  send(res, status, { error: message });
}

/** Split pathname into clean, non-empty segments. */
function segments(pathname: string): string[] {
  return pathname.split("/").filter(Boolean);
}

// ── Router ───────────────────────────────────────────────────────────────────

export class Router {
  private userSvc: UserService;
  private projectSvc: ProjectService;
  private taskSvc: TaskService;
  private commentSvc: CommentService;
  private notifSvc: NotificationService;

  constructor(
    userSvc: UserService,
    projectSvc: ProjectService,
    taskSvc: TaskService,
    commentSvc: CommentService,
    notifSvc: NotificationService
  ) {
    this.userSvc = userSvc;
    this.projectSvc = projectSvc;
    this.taskSvc = taskSvc;
    this.commentSvc = commentSvc;
    this.notifSvc = notifSvc;
  }

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const baseUrl = `http://${req.headers.host ?? "localhost"}`;
    const url = new URL(req.url ?? "/", baseUrl);
    const pathname = url.pathname;
    const method = req.method ?? "GET";
    const segs = segments(pathname);

    try {
      // ── /users ──────────────────────────────────────────────────────────
      if (segs[0] === "users") {
        await this.handleUsers(req, res, method, segs, url);
        return;
      }

      // ── /projects ───────────────────────────────────────────────────────
      if (segs[0] === "projects") {
        await this.handleProjects(req, res, method, segs, url);
        return;
      }

      // ── /tasks ──────────────────────────────────────────────────────────
      if (segs[0] === "tasks") {
        await this.handleTasks(req, res, method, segs, url);
        return;
      }

      // ── /comments ───────────────────────────────────────────────────────
      if (segs[0] === "comments") {
        await this.handleComments(req, res, method, segs, url);
        return;
      }

      // ── /notifications ──────────────────────────────────────────────────
      if (segs[0] === "notifications") {
        await this.handleNotifications(req, res, method, segs, url);
        return;
      }

      sendError(res, 404, "Route not found.");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Internal server error.";
      sendError(res, 500, message);
    }
  }

  // ── /users handlers ────────────────────────────────────────────────────────

  private async handleUsers(
    req: IncomingMessage,
    res: ServerResponse,
    method: string,
    segs: string[],
    _url: URL
  ): Promise<void> {
    // GET /users
    if (segs.length === 1 && method === "GET") {
      send(res, 200, this.userSvc.listAll());
      return;
    }

    // POST /users
    if (segs.length === 1 && method === "POST") {
      const body = await readBody(req) as Record<string, unknown>;
      const user = this.userSvc.create({
        name: body.name as string,
        email: body.email as string,
      });
      send(res, 201, user);
      return;
    }

    // GET /users/:id
    if (segs.length === 2 && method === "GET") {
      const user = this.userSvc.getById(segs[1]);
      if (!user) { sendError(res, 404, "User not found."); return; }
      send(res, 200, user);
      return;
    }

    // PUT /users/:id
    if (segs.length === 2 && method === "PUT") {
      const body = await readBody(req) as Record<string, unknown>;
      const user = this.userSvc.update(segs[1], {
        name: body.name as string | undefined,
        email: body.email as string | undefined,
      });
      if (!user) { sendError(res, 404, "User not found."); return; }
      send(res, 200, user);
      return;
    }

    // DELETE /users/:id
    if (segs.length === 2 && method === "DELETE") {
      const deleted = this.userSvc.delete(segs[1]);
      if (!deleted) { sendError(res, 404, "User not found."); return; }
      res.writeHead(204);
      res.end();
      return;
    }

    sendError(res, 405, "Method not allowed.");
  }

  // ── /projects handlers ─────────────────────────────────────────────────────

  private async handleProjects(
    req: IncomingMessage,
    res: ServerResponse,
    method: string,
    segs: string[],
    _url: URL
  ): Promise<void> {
    // GET /projects
    if (segs.length === 1 && method === "GET") {
      send(res, 200, this.projectSvc.listAll());
      return;
    }

    // POST /projects
    if (segs.length === 1 && method === "POST") {
      const body = await readBody(req) as Record<string, unknown>;
      const project = this.projectSvc.create({
        name: body.name as string,
        description: body.description as string,
      });
      send(res, 201, project);
      return;
    }

    // GET /projects/:id
    if (segs.length === 2 && method === "GET") {
      const project = this.projectSvc.getById(segs[1]);
      if (!project) { sendError(res, 404, "Project not found."); return; }
      send(res, 200, project);
      return;
    }

    // PUT /projects/:id
    if (segs.length === 2 && method === "PUT") {
      const body = await readBody(req) as Record<string, unknown>;
      const project = this.projectSvc.update(segs[1], {
        name: body.name as string | undefined,
        description: body.description as string | undefined,
      });
      if (!project) { sendError(res, 404, "Project not found."); return; }
      send(res, 200, project);
      return;
    }

    // DELETE /projects/:id
    if (segs.length === 2 && method === "DELETE") {
      const deleted = this.projectSvc.delete(segs[1]);
      if (!deleted) { sendError(res, 404, "Project not found."); return; }
      res.writeHead(204);
      res.end();
      return;
    }

    // POST /projects/:id/members  — add member
    if (segs.length === 3 && segs[2] === "members" && method === "POST") {
      const body = await readBody(req) as Record<string, unknown>;
      const userId = body.userId as string;
      if (!userId) { sendError(res, 400, "userId is required."); return; }

      const project = this.projectSvc.addMember(segs[1], userId);
      if (!project) { sendError(res, 404, "Project not found."); return; }
      send(res, 200, project);
      return;
    }

    // DELETE /projects/:id/members  — remove member
    if (segs.length === 3 && segs[2] === "members" && method === "DELETE") {
      const body = await readBody(req) as Record<string, unknown>;
      const userId = body.userId as string;
      if (!userId) { sendError(res, 400, "userId is required."); return; }

      const project = this.projectSvc.removeMember(segs[1], userId);
      if (!project) { sendError(res, 404, "Project not found."); return; }
      send(res, 200, project);
      return;
    }

    sendError(res, 405, "Method not allowed.");
  }

  // ── /tasks handlers ────────────────────────────────────────────────────────

  private async handleTasks(
    req: IncomingMessage,
    res: ServerResponse,
    method: string,
    segs: string[],
    url: URL
  ): Promise<void> {
    // GET /tasks?projectId=...
    if (segs.length === 1 && method === "GET") {
      const projectId = url.searchParams.get("projectId");
      if (!projectId) {
        sendError(res, 400, "Query parameter 'projectId' is required.");
        return;
      }
      send(res, 200, this.taskSvc.listByProject(projectId));
      return;
    }

    // POST /tasks
    if (segs.length === 1 && method === "POST") {
      const body = await readBody(req) as Record<string, unknown>;
      const task = this.taskSvc.create({
        title: body.title as string,
        description: body.description as string,
        projectId: body.projectId as string,
      });
      send(res, 201, task);
      return;
    }

    // GET /tasks/:id
    if (segs.length === 2 && method === "GET") {
      const task = this.taskSvc.getById(segs[1]);
      if (!task) { sendError(res, 404, "Task not found."); return; }
      send(res, 200, task);
      return;
    }

    // PUT /tasks/:id
    if (segs.length === 2 && method === "PUT") {
      const body = await readBody(req) as Record<string, unknown>;
      const task = this.taskSvc.update(segs[1], {
        title: body.title as string | undefined,
        description: body.description as string | undefined,
      });
      if (!task) { sendError(res, 404, "Task not found."); return; }
      send(res, 200, task);
      return;
    }

    // DELETE /tasks/:id
    if (segs.length === 2 && method === "DELETE") {
      const deleted = this.taskSvc.delete(segs[1]);
      if (!deleted) { sendError(res, 404, "Task not found."); return; }
      res.writeHead(204);
      res.end();
      return;
    }

    // PUT /tasks/:id/status
    if (segs.length === 3 && segs[2] === "status" && method === "PUT") {
      const body = await readBody(req) as Record<string, unknown>;
      const newStatus = body.status as TaskStatus;
      if (!newStatus) { sendError(res, 400, "status is required."); return; }

      // Existence check first so we can return 404 vs 400 correctly
      const existing = this.taskSvc.getById(segs[1]);
      if (!existing) { sendError(res, 404, "Task not found."); return; }

      try {
        const task = this.taskSvc.changeStatus(segs[1], newStatus);
        send(res, 200, task);
      } catch (err) {
        const message = err instanceof Error ? err.message : "Invalid status transition.";
        sendError(res, 400, message);
      }
      return;
    }

    // PUT /tasks/:id/assign
    if (segs.length === 3 && segs[2] === "assign" && method === "PUT") {
      const body = await readBody(req) as Record<string, unknown>;
      const assigneeId = body.assigneeId as string;
      if (!assigneeId) { sendError(res, 400, "assigneeId is required."); return; }

      const task = this.taskSvc.assignTask(segs[1], assigneeId);
      if (!task) { sendError(res, 404, "Task not found."); return; }
      send(res, 200, task);
      return;
    }

    sendError(res, 405, "Method not allowed.");
  }

  // ── /comments handlers ─────────────────────────────────────────────────────

  private async handleComments(
    req: IncomingMessage,
    res: ServerResponse,
    method: string,
    segs: string[],
    url: URL
  ): Promise<void> {
    // GET /comments?taskId=...
    if (segs.length === 1 && method === "GET") {
      const taskId = url.searchParams.get("taskId");
      if (!taskId) {
        sendError(res, 400, "Query parameter 'taskId' is required.");
        return;
      }
      send(res, 200, this.commentSvc.listByTask(taskId));
      return;
    }

    // POST /comments
    // The router resolves task title and author name before calling the service,
    // keeping services decoupled from each other.
    if (segs.length === 1 && method === "POST") {
      const body = await readBody(req) as Record<string, unknown>;
      const taskId = body.taskId as string;
      const authorId = body.authorId as string;

      if (!taskId) { sendError(res, 400, "taskId is required."); return; }
      if (!authorId) { sendError(res, 400, "authorId is required."); return; }

      // Resolve cross-service data at the router layer (allowed — router is the
      // single entry point and may read from multiple services to build context).
      const task = this.taskSvc.getById(taskId);
      if (!task) { sendError(res, 404, "Task not found."); return; }

      const author = this.userSvc.getById(authorId);
      if (!author) { sendError(res, 404, "Author (user) not found."); return; }

      const comment = this.commentSvc.create({
        taskId,
        authorId,
        body: body.body as string,
        taskTitle: task.title,
        authorName: author.name,
      });
      send(res, 201, comment);
      return;
    }

    // GET /comments/:id
    if (segs.length === 2 && method === "GET") {
      const comment = this.commentSvc.getById(segs[1]);
      if (!comment) { sendError(res, 404, "Comment not found."); return; }
      send(res, 200, comment);
      return;
    }

    // DELETE /comments/:id
    if (segs.length === 2 && method === "DELETE") {
      const deleted = this.commentSvc.delete(segs[1]);
      if (!deleted) { sendError(res, 404, "Comment not found."); return; }
      res.writeHead(204);
      res.end();
      return;
    }

    sendError(res, 405, "Method not allowed.");
  }

  // ── /notifications handlers ────────────────────────────────────────────────

  private async handleNotifications(
    req: IncomingMessage,
    res: ServerResponse,
    method: string,
    segs: string[],
    url: URL
  ): Promise<void> {
    // GET /notifications?userId=...
    if (segs.length === 1 && method === "GET") {
      const userId = url.searchParams.get("userId");
      if (!userId) {
        sendError(res, 400, "Query parameter 'userId' is required.");
        return;
      }
      send(res, 200, this.notifSvc.listByUser(userId));
      return;
    }

    // PUT /notifications/:id/read
    if (segs.length === 3 && segs[2] === "read" && method === "PUT") {
      const notification = this.notifSvc.markAsRead(segs[1]);
      if (!notification) { sendError(res, 404, "Notification not found."); return; }
      send(res, 200, notification);
      return;
    }

    sendError(res, 405, "Method not allowed.");
  }
}

